/**
 * Pins, hashes and licence pointers for the speech component we serve.
 *
 * The record itself is `public/voice/espeak/build-manifest.json`, generated by
 * `scripts/voice-manifest.mjs` from the pinned artifact hashes; that script
 * refuses to write a manifest whose files do not match the pins, and
 * `assetManifest.test.ts` re-checks every shipped file against it, so a swapped
 * or truncated asset fails the suite instead of shipping quietly.
 *
 * At runtime the same file is the loader's contract: `public/voice/espeak/espeakng.bootstrap.js`
 * fetches each object file, checks its length and SHA-256, and refuses to start
 * the module unless they match (see its header). A mismatch therefore fails
 * closed: the narrator reports an error rather than phonemizing with an unknown
 * build.
 *
 * No third-party component is bundled into the application bundle. These files
 * are served as separate static assets from the same origin as the notices and
 * the corresponding source.
 */
export const VOICE_MANIFEST_URL = '/voice/espeak/build-manifest.json'

export interface VoiceAsset {
  role: 'worker-js' | 'wasm' | 'data'
  file: string
  bytes: number
  sha256: string
  licences: string[]
}

export interface VoiceNotice {
  component: string
  licence: string
  file: string
}

export interface VoiceBuildManifest {
  component: string
  upstream: { project: string; repository: string; tag: string; commit: string; licence: string; licenceText: string; warranty: string }
  toolchain: { emscripten: string; releaseHash: string; target: string; configureFlags: string[] }
  modifications: { status: string; date: string; record: string; fullRecord: string; patches: { file: string; why: string }[] }
  objectCode: VoiceAsset[]
  correspondingSource: { file: string; offer: string; bytes: number; sha256: string; files: number; note: string }
  notices: VoiceNotice[]
  noticeIndex: string
  shipped: string
}

const HASH = /^[0-9a-f]{64}$/
const COMMIT = /^[0-9a-f]{40}$/
const ROLES = ['worker-js', 'wasm', 'data']

function assert(condition: unknown, reason: string): asserts condition {
  if (!condition) throw Error(`MANIFEST_INVALID:${reason}`)
}

/** Reads and validates the shipped manifest. Throws rather than returning a partial record. */
export async function loadVoiceManifest(fetcher: typeof fetch = fetch, url: string = VOICE_MANIFEST_URL): Promise<VoiceBuildManifest> {
  const response = await fetcher(url, { credentials: 'omit' })
  if (!response.ok) throw Error(`MANIFEST_UNAVAILABLE:${response.status}`)
  const manifest = await response.json() as VoiceBuildManifest
  assert(manifest && typeof manifest === 'object', 'shape')
  assert(COMMIT.test(manifest.upstream?.commit ?? ''), 'commit')
  assert(manifest.correspondingSource && HASH.test(manifest.correspondingSource.sha256), 'source-hash')
  assert(manifest.correspondingSource.bytes > 0 && manifest.correspondingSource.offer, 'source')
  for (const role of ROLES) {
    const asset = manifest.objectCode?.find(entry => entry.role === role)
    assert(asset && HASH.test(asset.sha256) && asset.bytes > 0 && asset.file, `object:${role}`)
  }
  assert(manifest.notices?.length > 0 && manifest.notices.every(entry => entry.file && entry.licence), 'notices')
  assert(manifest.noticeIndex, 'notice-index')
  return manifest
}

/** Absolute URL for a path recorded in the manifest, which is relative to the manifest itself. */
export function manifestPath(path: string, url: string = VOICE_MANIFEST_URL): string {
  return new URL(path, new URL(url, window.location.href)).href
}
